3023: def _parse_partial_date_for_range_check(date_str, for_min_comparison=True, filtername=""):
3024:     """
3025:     Parse partial dates with range-aware handling for comparison.
3026:     
3027:     When comparing partial dates (year-only or year-month) against specific dates,
3028:     we need to handle them based on the comparison direction:
3029:     
3030:     - For min_collection_date comparisons: use the END of the partial range
3031:       (e.g., "2015" -> 2015-12-31, "2015-06" -> 2015-06-30)
3032:       This ensures records from that year/month are included if they COULD be >= min.
3033:       
3034:     - For max_collection_date comparisons: use the START of the partial range
3035:       (e.g., "2015" -> 2015-01-01, "2015-06" -> 2015-06-01)
3036:       This ensures records from that year/month are included if they COULD be <= max.
3037:     
3038:     Args:
3039:         date_str (str): Date string to parse (various formats).
3040:         for_min_comparison (bool): True if comparing against min date, False for max date.
3041:         filtername (str): Name of the filter for error messages.
3042:         
3043:     Returns:
3044:         datetime: Parsed datetime object with partial dates adjusted appropriately.
3045:         
3046:     Raises:
3047:         ValueError: If date parsing fails.
3048:     """    
3049:     if not date_str or not date_str.strip():
3050:         raise ValueError(f"Empty date string for {filtername}")
3051:     
3052:     date_str = date_str.strip()
3053:     
3054:     # Detect date precision based on format
3055:     # Year-only: "2015" or "2015" (4 digits)
3056:     # Year-month: "2015-06", "2015/06", "Jun 2015", etc.
3057:     # Full date: "2015-06-15", "2015/06/15", "Jun 15, 2015", etc.
3058:     
3059:     year_only_pattern = r'^(\d{4})$'
3060:     year_month_pattern = r'^(\d{4})[-/](\d{1,2})$'
3061:     
3062:     year_match = re.match(year_only_pattern, date_str)
3063:     year_month_match = re.match(year_month_pattern, date_str)
3064:     
3065:     try:
3066:         if year_match:
3067:             # Year-only date like "2015"
3068:             year = int(year_match.group(1))
3069:             if for_min_comparison:
3070:                 # For min comparison, use end of year (Dec 31)
3071:                 result = datetime(year, 12, 31)
3072:                 logger.debug("Parsed year-only date '%s' as %s (end of year for min comparison)", 
